const worlds={space:{name:'Spazio',icon:'🚀',accent:'#6356d7',tint:'#f0edff',hero:'#e6e2ff',line:'#dad5f4',mission:'Accendi il razzo delle parole. Ogni parola scritta ti avvicina a un nuovo pianeta.',success:'Lancio riuscito!',reward:'🪐',verb:'Una parola, un passo nello spazio!'},animals:{name:'Animali',icon:'🐾',accent:'#258579',tint:'#e4f5ef',hero:'#d6eee5',line:'#c5e2d9',mission:'Esplora il sentiero degli animali. Ogni parola è una nuova scoperta.',success:'Esplorazione completata!',reward:'🐾',verb:'Una parola, una nuova scoperta!'},dino:{name:'Dinosauri',icon:'🦕',accent:'#568333',tint:'#edf5dd',hero:'#deebc5',line:'#d3e1bd',mission:'Parti per la valle dei dinosauri. Raccogli impronte con le tue parole.',success:'Spedizione completata!',reward:'🦖',verb:'Hai trovato una nuova impronta!'},sport:{name:'Sport',icon:'⚽',accent:'#d16632',tint:'#fff0e4',hero:'#ffe1ca',line:'#f1d4c0',mission:'Entra in campo! Ascolta, allenati e segna un punto con ogni parola.',success:'Grande squadra!',reward:'🏆',verb:'Un punto per il tuo allenamento!'},ocean:{name:'Oceano',icon:'🐬',accent:'#287db1',tint:'#e4f4fc',hero:'#d0eaf9',line:'#c3dfee',mission:'Salpa per un viaggio sott’acqua. Ogni parola ti porta verso un nuovo tesoro.',success:'Tesoro trovato!',reward:'🐚',verb:'Un altro passo verso il tesoro!'},creative:{name:'Creatività',icon:'🎨',accent:'#b34e86',tint:'#fceaf4',hero:'#f6d9ec',line:'#eccbdf',mission:'Entra nel laboratorio delle idee. Raccogli colori e crea con le parole.',success:'Capolavoro completato!',reward:'🖌️',verb:'Una nuova idea prende forma!'}};
let playerSettings={};try{playerSettings=JSON.parse(localStorage.getItem('wordQuestPlayer')||'{}')}catch{}
let worldId=worlds[playerSettings.world]?playerSettings.world:'space',playerName=typeof playerSettings.name==='string'?playerSettings.name.slice(0,20):'',avatar=['🦊','🐼','🤖','🐉','🐱','🐙','🦁','🐧'].includes(playerSettings.avatar)?playerSettings.avatar:'🦊';
function rememberPlayer(){try{localStorage.setItem('wordQuestPlayer',JSON.stringify({world:worldId,name:playerName,avatar}))}catch{}}
function currentWorld(){return worlds[worldId]}
function setWorld(id){worldId=id;let w=currentWorld();for(let k of ['accent','tint','hero','line'])document.documentElement.style.setProperty('--'+k,w[k]);document.documentElement.style.setProperty('--green',w.accent);document.querySelectorAll('[data-world]').forEach(b=>{let active=b.dataset.world===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.querySelector('.worldCheck').textContent=active?'✓':''});rememberPlayer();if(typeof home==='function'&&document.querySelector('#game').dataset.active!=='true')home()}
function initWorlds(){document.querySelector('#worlds').innerHTML=Object.entries(worlds).map(([id,w])=>'<button class="world" data-world="'+id+'" aria-pressed="false"><span class="worldCheck"></span><span class="worldIcon" aria-hidden="true">'+w.icon+'</span><b>'+w.name+'</b></button>').join('');document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{setWorld(b.dataset.world);const active=document.querySelector('#game').dataset.active==='true';if(active){let label=document.querySelector('#worldLabel');if(label)label.textContent=currentWorld().icon+' '+currentWorld().name}});document.querySelector('#editPlayer').onclick=()=>{document.querySelector('#playerEditor').hidden=false;document.querySelector('#nickname').value=playerName;drawAvatars()};document.querySelector('#cancelPlayer').onclick=()=>document.querySelector('#playerEditor').hidden=true;document.querySelector('#playerForm').onsubmit=e=>{e.preventDefault();playerName=document.querySelector('#nickname').value.trim().slice(0,20);rememberPlayer();refreshPlayer();document.querySelector('#playerEditor').hidden=true;if(document.querySelector('#game').dataset.active!=='true')home()};refreshPlayer();setWorld(worldId)}
function refreshPlayer(){document.querySelector('#playerDisplay').textContent=playerName||'Il tuo personaggio';document.querySelector('#avatarDisplay').textContent=avatar}
function drawAvatars(){document.querySelector('#avatars').innerHTML=['🦊','🐼','🤖','🐉','🐱','🐙','🦁','🐧'].map(a=>'<button type="button" class="avatarOption '+(a===avatar?'selected':'')+'" aria-label="Personaggio '+a+'" aria-pressed="'+(a===avatar)+'">'+a+'</button>').join('');document.querySelectorAll('.avatarOption').forEach(b=>b.onclick=()=>{avatar=b.textContent;drawAvatars()})}
